// AVANCE CAJA (solo lectura) -- resuelve la carpeta SAP oficial de la caja pedida.
// Es la MISMA carpeta y la MISMA variable de entorno que usa la publicacion oficial y
// GLOBAL (DRIVE_SAP_<TIQ|AME>, default historico solo para TIQUIPAYA; AMERICA sin default y
// sin fallback al folder de TIQUIPAYA: falla cerrado con motivo, ver config_drive_oficial.py).
// Config por caja, no ramas: agregar una caja = una fila aqui + su entrada en config_cajas.py
// (tests_v3/n8n_avance_caja verifica que ambas tablas coincidan).
const CAJAS = {
  tiquipaya: { env: 'DRIVE_SAP_TIQ', porDefecto: '1mid4gUHnCmZbISlsAYMwWta3RudTSE13' },
  america: { env: 'DRIVE_SAP_AME', porDefecto: null },
};
const q = ($('WEBHOOK avance').first().json.query || {});
const caja = String(q.caja || 'tiquipaya').trim().toLowerCase();
const cfg = Object.prototype.hasOwnProperty.call(CAJAS, caja) ? CAJAS[caja] : null;
if (!cfg) {
  return [{ json: { caja: caja, folder_sap_id: null, motivo: 'CAJA_DESCONOCIDA' } }];
}
const folderId = $env[cfg.env] || cfg.porDefecto;
if (!folderId) {
  return [{ json: { caja: caja, folder_sap_id: null, motivo: cfg.env + '_NO_CONFIGURADA' } }];
}
return [{ json: { caja: caja, folder_sap_id: folderId, motivo: null } }];

// AVANCE CAJA (solo lectura): n8n solo lista nombres de archivo de la carpeta SAP oficial;
// que fechas cuentan como procesadas y donde se corta la continuidad lo decide Python
// (v3/avance_caja.py, unica autoridad).
const r = $('RESOLVER - Carpeta SAP de la caja').first().json;
const nombres = $input.all()
  .map(function (it) { return it.json && it.json.name; })
  .filter(function (n) { return typeof n === 'string' && n; });
const executionId = ($execution && $execution.id) ? $execution.id : String(Date.now());

const payload = { caja: r.caja, nombres_archivos: nombres };

const rutaInputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_avance_caja_input_' + executionId + '.json';
const rutaOutputTmp = '' + ($env.TIQ_BASE_DIR || "/home/codespace/.n8n-files") + '/tiq_v3_tmp/tiq_v3_dev_api_avance_caja_output_' + executionId + '.json';

return [{
  json: {
    input_b64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
    ruta_input_tmp: rutaInputTmp,
    ruta_output_tmp: rutaOutputTmp,
  },
}];

// Sin carpeta SAP configurada para esta caja (p. ej. DRIVE_SAP_AME sin definir): no se
// consulta Drive ni se inventa un avance; la interfaz solo muestra "no disponible".
const r = $input.first().json;
return [{ json: { resultado: 'OK', disponible: false, caja: r.caja, motivo: r.motivo } }];
